import sqlite3, math, json
from collections import defaultdict

DB_PATH = '/app/manufacturing.db'
conn = sqlite3.connect(DB_PATH)
conn.row_factory = sqlite3.Row
cur = conn.cursor()

parts = {}
for r in cur.execute('SELECT part_id, name, on_hand_qty, batch_size FROM parts'):
    parts[r['part_id']] = {
        'name': r['name'],
        'on_hand_qty': int(r['on_hand_qty']),
        'batch_size': int(r['batch_size'])
    }

bom_rows = []
for r in cur.execute('SELECT parent_part_id, child_part_id, qty_per, scrap_rate_pct, setup_scrap_qty FROM bom'):
    bom_rows.append({
        'parent': r['parent_part_id'],
        'child': r['child_part_id'],
        'qty_per': int(r['qty_per']),
        'scrap_rate_pct': float(r['scrap_rate_pct']),
        'setup_scrap_qty': int(r['setup_scrap_qty'])
    })

routing = defaultdict(list)
for r in cur.execute('SELECT parent_part_id, workcenter_id, setup_hours, run_hours_per_unit FROM routing'):
    routing[r['parent_part_id']].append({
        'wc': r['workcenter_id'],
        'setup': float(r['setup_hours']),
        'run': float(r['run_hours_per_unit'])
    })

workcenters = {}
for r in cur.execute('SELECT workcenter_id, name, available_hours FROM workcenters'):
    workcenters[r['workcenter_id']] = {
        'name': r['name'],
        'available_hours': float(r['available_hours'])
    }

subs = defaultdict(list)
for r in cur.execute('SELECT primary_part_id, substitute_part_id, qty_ratio, preference_rank FROM substitutes'):
    subs[r['primary_part_id']].append({
        'sub': r['substitute_part_id'],
        'ratio': float(r['qty_ratio']),
        'rank': int(r['preference_rank'])
    })
for k in subs:
    subs[k].sort(key=lambda x: (x['rank'], x['sub']))

orders = []
for r in cur.execute('SELECT order_id, product_part_id, requested_qty, priority FROM orders'):
    orders.append({
        'order_id': r['order_id'],
        'product_part_id': r['product_part_id'],
        'requested_qty': int(r['requested_qty']),
        'priority': int(r['priority'])
    })
conn.close()

orders.sort(key=lambda x: (x['priority'], x['order_id']))

manufactured = set(routing.keys()) | {b['parent'] for b in bom_rows}
children_by_parent = defaultdict(list)
for b in bom_rows:
    children_by_parent[b['parent']].append(b)

# Low-level codes: longest path from top-level parts; higher level means closer to final product.
level = {p: 0 for p in parts}
changed = True
while changed:
    changed = False
    for b in bom_rows:
        nl = level[b['parent']] + 1
        if level[b['child']] < nl:
            level[b['child']] = nl
            changed = True
# Highest level first, then by part_id for determinism.
sorted_parts = sorted(parts.keys(), key=lambda p: (level[p], p))


def explode(product_id, order_qty, inv):
    """Return total gross leaf demand, build quantities, workcenter usage,
       and projected inventory after applying builds.
    """
    demand = defaultdict(int)
    demand[product_id] = order_qty
    build = {}
    work_usage = defaultdict(float)
    proj = dict(inv)

    for p in sorted_parts:
        if p not in manufactured:
            continue
        d = demand.get(p, 0)
        if d <= 0:
            continue
        on_hand = proj.get(p, 0)
        net = d - on_hand
        b = 0
        if net > 0:
            batch = parts[p]['batch_size']
            b = math.ceil(net / batch) * batch
        build[p] = b

        if b > 0:
            for rr in routing.get(p, []):
                work_usage[rr['wc']] += rr['setup'] + b * rr['run']
            for child in children_by_parent.get(p, []):
                base = b * child['qty_per']
                child_req = int(math.ceil(base * (1.0 + child['scrap_rate_pct'] / 100.0))) + child['setup_scrap_qty']
                demand[child['child']] += child_req

        proj[p] = proj.get(p, 0) - d + b

    return dict(demand), build, dict(work_usage), proj


def available_leaf_units(leaf, inv):
    avail = inv.get(leaf, 0)
    for s in subs.get(leaf, []):
        st = inv.get(s['sub'], 0)
        if st > 0 and s['ratio'] > 0:
            avail += math.floor(st / s['ratio'])
    return avail


def consume_leaves(leaf_demand, inv):
    """Return consumption dict or None if leaf/substitute inventory is insufficient."""
    remaining = dict(inv)
    primary_consumed = defaultdict(int)
    sub_consumed = defaultdict(float)

    for leaf, dem in sorted(leaf_demand.items()):
        if dem <= 0:
            continue
        rem = dem

        # Primary stock first.
        use = min(rem, remaining.get(leaf, 0))
        if use > 0:
            primary_consumed[leaf] += use
            remaining[leaf] = remaining.get(leaf, 0) - use
            rem -= use

        if rem <= 0:
            continue

        for cand in subs.get(leaf, []):
            if rem <= 0:
                break
            stock = remaining.get(cand['sub'], 0)
            if stock <= 0 or cand['ratio'] <= 0:
                continue
            equiv_units = math.floor(stock / cand['ratio'])
            use = min(rem, equiv_units)
            if use <= 0:
                continue
            consumed_sub_qty = use * cand['ratio']
            sub_consumed[cand['sub']] += consumed_sub_qty
            remaining[cand['sub']] = stock - consumed_sub_qty
            rem -= use

        if rem > 0:
            return None

    return {
        'primary': dict(primary_consumed),
        'subs': dict(sub_consumed)
    }


current_parts = {p: parts[p]['on_hand_qty'] for p in parts}
current_wc = {wc: workcenters[wc]['available_hours'] for wc in workcenters}
report_orders = []
EPS = 1e-9

for o in orders:
    oid = o['order_id']
    product = o['product_part_id']
    req = o['requested_qty']
    batch = parts[product]['batch_size']

    max_multiple = (req // batch) * batch
    candidates = list(range(max_multiple, -1, -batch))
    if 0 not in candidates:
        candidates.append(0)

    selected = None
    selected_demand = None
    selected_build = None
    selected_work = None
    selected_proj = None
    selected_cons = None

    for cand in candidates:
        dem_all, build, work_use, proj = explode(product, cand, current_parts)
        leaf_demand = {p: d for p, d in dem_all.items() if p not in manufactured and d > 0}

        feasible = True
        for wc, usage in work_use.items():
            if usage > current_wc[wc] + EPS:
                feasible = False
                break

        if feasible:
            cons = consume_leaves(leaf_demand, current_parts)
            if cons is None:
                feasible = False

        if feasible:
            selected = cand
            selected_demand = dem_all
            selected_build = build
            selected_work = work_use
            selected_proj = proj
            selected_cons = cons
            break

    if selected is None:
        selected = 0
        _, _, _, proj_zero = explode(product, 0, current_parts)
        selected_demand = {}
        selected_build = {}
        selected_work = {}
        selected_proj = proj_zero
        selected_cons = {'primary': {}, 'subs': {}}

    # Determine limiting resource when order is not fully satisfied.
    limiting = None
    if selected < req:
        try_qty = selected + batch
        dem_all_lim, _, work_use_lim, _ = explode(product, try_qty, current_parts)
        leaf_gross = {p: d for p, d in dem_all_lim.items() if p not in manufactured and d > 0}
        ratios = []

        for leaf, d in leaf_gross.items():
            if d <= 0:
                continue
            avail = available_leaf_units(leaf, current_parts)
            ratio = avail / d
            if ratio < 1.0 - EPS:
                ratios.append((ratio, leaf))

        for wc, usage in work_use_lim.items():
            if usage <= 0:
                continue
            ratio = current_wc[wc] / usage
            if ratio < 1.0 - EPS:
                ratios.append((ratio, wc))

        if ratios:
            ratios.sort(key=lambda x: (x[0], x[1]))
            limiting = ratios[0][1]

    report_orders.append({
        'order_id': oid,
        'allocated_qty': int(selected),
        'shortfall_qty': int(req - selected),
        'limiting_resource': limiting
    })

    # Commit the selected production.
    current_parts = dict(selected_proj)
    for leaf, qty in selected_cons['primary'].items():
        current_parts[leaf] = current_parts.get(leaf, 0) - qty
    for sub, qty in selected_cons['subs'].items():
        current_parts[sub] = current_parts.get(sub, 0) - qty
    for wc, usage in selected_work.items():
        current_wc[wc] = current_wc[wc] - usage

report_orders_sorted = sorted(report_orders, key=lambda x: x['order_id'])
report = {'orders': report_orders_sorted}

with open('/app/report.json', 'w') as f:
    json.dump(report, f, indent=2)
    f.write('\n')

print(json.dumps(report, indent=2))
